import{bV as a,aL as i,u as e,G as o}from"./chunks/framework.DvBUyM1S.js";const r=JSON.parse('{"title":"Dockge 部署（Docker Compose 管理面板）标准步骤","description":"","frontmatter":{"id":"PB-20260908-001","type":"playbook","title":"Dockge 部署（Docker Compose 管理面板）标准步骤","tags":["docker","dockge","compose","self-host"],"status":"draft","source":"conversation:2026-09-08","created":"2026-09-08T00:00:00.000Z","updated":"2026-09-08T00:00:00.000Z"},"headers":[],"relativePath":"playbooks/dockge-deploy.md","filePath":"playbooks/dockge-deploy.md"}'),t={name:"playbooks/dockge-deploy.md"};function l(n,s,p,k,h,c){return i(),e("div",null,[...s[0]||(s[0]=[o(`<h1 id="dockge-部署-docker-compose-管理面板-标准步骤" tabindex="-1">Dockge 部署（Docker Compose 管理面板）标准步骤 <a class="header-anchor" href="#dockge-部署-docker-compose-管理面板-标准步骤" aria-label="Permalink to &quot;Dockge 部署（Docker Compose 管理面板）标准步骤&quot;">​</a></h1><p>Dockge（louislam/dockge）是 compose.yaml 导向的可视化栈管理器：创建/编辑/启停/重启/删除 stack，支持 <code>docker run</code> 命令转 compose。适合作为自部署 AI 网关（如 New API）等多 stack 的统一管理面板。</p><h2 id="_1-linux-服务器标准部署-compose-方式" tabindex="-1">1. Linux 服务器标准部署（compose 方式） <a class="header-anchor" href="#_1-linux-服务器标准部署-compose-方式" aria-label="Permalink to &quot;1. Linux 服务器标准部署（compose 方式）&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/stacks</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/dockge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/dockge</span></span></code></pre></div><p>新建 <code>compose.yaml</code>：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  dockge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">louislam/dockge:1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    restart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">unless-stopped</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    ports</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;5001:5001&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    volumes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/var/run/docker.sock:/var/run/docker.sock</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./data:/app/data</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/opt/stacks:/opt/stacks</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DOCKGE_STACKS_DIR=/opt/stacks</span></span></code></pre></div><p>启动：<code>docker compose up -d</code>，访问 <code>http://服务器IP:5001</code>，首次进入设置管理员账号密码。</p><h2 id="_2-关键点-踩坑点" tabindex="-1">2. 关键点（踩坑点） <a class="header-anchor" href="#_2-关键点-踩坑点" aria-label="Permalink to &quot;2. 关键点（踩坑点）&quot;">​</a></h2><ul><li><strong><code>DOCKGE_STACKS_DIR</code> 必须与挂载的 stacks 目录一致</strong>，否则看不到已有 stack。</li><li><code>/var/run/docker.sock</code> 是必须项，Dockge 靠它控制本机 Docker。</li><li>端口冲突：改 <code>ports</code> 左侧映射端口即可，右侧 5001 不动。</li><li>Windows / 群晖 / NAS：用同一 compose 文件，把 <code>docker.sock</code> 与 stacks 路径换成对应平台路径（NAS 通常在 Docker UI 里勾选「高权限/挂载 docker.sock」）。</li></ul><h2 id="_3-备选方式" tabindex="-1">3. 备选方式 <a class="header-anchor" href="#_3-备选方式" aria-label="Permalink to &quot;3. 备选方式&quot;">​</a></h2><p>一键脚本安装（等价上面的 compose，默认装到 <code>/opt/dockge</code>）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://get.dockge.io</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><h2 id="_4-多机管理-远程-docker" tabindex="-1">4. 多机管理（远程 Docker） <a class="header-anchor" href="#_4-多机管理-远程-docker" aria-label="Permalink to &quot;4. 多机管理（远程 Docker）&quot;">​</a></h2><p>Dockge 本身管本机 Docker；要管理远程机器需在远程机器部署 dockge agent 并配置 SSH 连接，仅多机场景才需要。</p><h2 id="_5-部署后建议" tabindex="-1">5. 部署后建议 <a class="header-anchor" href="#_5-部署后建议" aria-label="Permalink to &quot;5. 部署后建议&quot;">​</a></h2><p>把业务 stack 的 compose 文件放进 <code>$DOCKGE_STACKS_DIR/&amp;lt;stack-name&amp;gt;/compose.yaml</code>（如 <code>/opt/stacks/newapi/compose.yaml</code>），Dockge 自动发现并可管理。</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><code>playbooks/ai-gateway-selection-comparison.md</code>（New API 等网关选型，常部署于 Dockge 管理下）</li><li><code>playbooks/new-api-token-usage-stats.md</code>（New API 部署后的用量统计配置）</li></ul>`,18)])])}const g=a(t,[["render",l]]);export{r as __pageData,g as default};
